// Offline license verification (Ed25519, node:crypto).
// License string = base64url(JSON payload) + "." + base64url(signature over the payload bytes).
// Issued by GO Along with scripts/license.ts using licenses/private.pem (never shipped to customers).
import { createPublicKey, sign as edSign, verify as edVerify, type KeyObject } from "node:crypto";

/** Public key of the GO Along license issuer (SPKI, base64 DER). Generated by `npx tsx scripts/license.ts keygen`. */
export const LICENSE_PUBLIC_KEY = "MCowBQYDK2VwAyEAetQn9AIUT/gDNtcsbg/73NxOg4Mjx6A0u+6eDLkLk2k=";

export interface LicensePayload {
  license_id: string;
  licensee: string;
  tax_id?: string;
  max_employees: number;
  modules: string[];
  issued_at: string; // ISO date
  support_until?: string; // ISO date — after this only support/updates end; the software keeps working
}

export interface LicenseStatus {
  valid: boolean;
  error?: string;
  license_id?: string;
  licensee?: string;
  tax_id?: string;
  max_employees?: number;
  modules?: string[];
  issued_at?: string;
  support_until?: string | null;
  support_expired?: boolean;
  checked_at: string;
}

export const b64url = {
  encode: (b: Buffer | string) => Buffer.from(b).toString("base64url"),
  decode: (s: string) => Buffer.from(s, "base64url"),
};

function publicKey(pem?: string): KeyObject {
  if (pem) return createPublicKey(pem);
  return createPublicKey({ key: Buffer.from(LICENSE_PUBLIC_KEY, "base64"), format: "der", type: "spki" });
}

/** Sign a payload (used by scripts/license.ts and tests) */
export function signLicense(payload: LicensePayload, privateKey: KeyObject | string): string {
  const body = b64url.encode(JSON.stringify(payload));
  const sig = edSign(null, Buffer.from(body), privateKey);
  return `${body}.${b64url.encode(sig)}`;
}

/** Verify a license string. `pubPem` overrides the embedded key (tests). Never throws. */
export function verifyLicense(license: string | null | undefined, opts: { pubPem?: string; now?: Date } = {}): LicenseStatus {
  const checked_at = (opts.now ?? new Date()).toISOString();
  const s = (license ?? "").trim().replace(/\s+/g, "");
  if (!s) return { valid: false, error: "ยังไม่ได้ใส่ License", checked_at };
  const parts = s.split(".");
  if (parts.length !== 2 || !parts[0] || !parts[1]) return { valid: false, error: "รูปแบบ License ไม่ถูกต้อง (ต้องเป็นข้อความ 2 ส่วนคั่นด้วยจุด)", checked_at };
  let ok = false;
  try {
    ok = edVerify(null, Buffer.from(parts[0]), publicKey(opts.pubPem), b64url.decode(parts[1]));
  } catch {
    ok = false;
  }
  if (!ok) return { valid: false, error: "ลายเซ็น License ไม่ถูกต้อง — License ถูกแก้ไขหรือไม่ได้ออกโดย GO Along", checked_at };
  let p: LicensePayload;
  try {
    p = JSON.parse(b64url.decode(parts[0]).toString("utf8"));
  } catch {
    return { valid: false, error: "อ่านข้อมูล License ไม่ได้", checked_at };
  }
  if (!p.licensee || !Number.isFinite(Number(p.max_employees)) || Number(p.max_employees) < 1) {
    return { valid: false, error: "ข้อมูลใน License ไม่ครบ", checked_at };
  }
  const today = checked_at.slice(0, 10);
  return {
    valid: true,
    license_id: p.license_id,
    licensee: p.licensee,
    tax_id: p.tax_id,
    max_employees: Number(p.max_employees),
    modules: p.modules ?? [],
    issued_at: p.issued_at,
    support_until: p.support_until ?? null,
    support_expired: !!p.support_until && p.support_until < today,
    checked_at,
  };
}
